If group delta is 0, object delta is from the decoded Location.  Otherwise it's from 0.

```
def decodeDelta(current, delta):
  return Location(current.group + delta.groupDelta,
                  (delta.groupDelta == 0 ? current.object : 0) + current.objectDelta)

current = Location{0,0}
while !ranges.empty:
  start = decodeDelta(current, ranges[0].start)
  end = decodeDelta(start, ranges[0].end)
  current = end
  ranges = ranges[1:]
